def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    last_my, last_opp = history[-1]
    if opp_d > n * 0.7:
        return 'D'
    if last_my == 'D' and last_opp == 'D':
        if rng.random() < 0.3:
            return 'C'
        return 'D'
    if last_opp == 'C':
        return 'C'
    else:
        if opp_d <= 2 and n > 10:
            if rng.random() < 0.5:
                return 'C'
        if rng.random() < 0.1:
            return 'C'
        return 'D'
